/*!50003 CREATE*/ /*!50017 DEFINER=`test`@`%`*/ /*!50003 TRIGGER sync_commission_grade_after_update 
AFTER UPDATE ON companies 
FOR EACH ROW 
BEGIN
    
    IF OLD.default_commission_grade != NEW.default_commission_grade THEN
        
        UPDATE performance_records 
        SET commission_rate = CASE 
            WHEN NEW.default_commission_grade = 'A' THEN 5.0
            WHEN NEW.default_commission_grade = 'B' THEN 4.5
            WHEN NEW.default_commission_grade = 'C' THEN 4.0
            WHEN NEW.default_commission_grade = 'D' THEN 3.5
            WHEN NEW.default_commission_grade = 'E' THEN 3.0
            ELSE commission_rate
        END
        WHERE company_id = NEW.id;
    END IF;
END */;;
DELIMITER ;
