CREATE DEFINER=`test`@`%` FUNCTION `calculate_absorption_rates`(p_settlement_month VARCHAR(7)) RETURNS text CHARSET utf8mb4 COLLATE utf8mb4_uca1400_ai_ci
    READS SQL DATA
    DETERMINISTIC
BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE v_company_id VARCHAR(36);
    DECLARE v_client_id BIGINT;
    DECLARE v_product_id VARCHAR(36);
    DECLARE v_prescription_qty DECIMAL(10,2);
    DECLARE v_commission_rate DECIMAL(5,2);
    DECLARE v_absorption_rate DECIMAL(5,2) DEFAULT 0;
    DECLARE updated_count INT DEFAULT 0;
    
    
    DECLARE absorption_cursor CURSOR FOR
        SELECT 
            company_id,
            client_id,
            product_id,
            prescription_qty,
            commission_rate
        FROM performance_records_absorption
        WHERE settlement_month = p_settlement_month;
    
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
    
    
    OPEN absorption_cursor;
    
    read_loop: LOOP
        FETCH absorption_cursor INTO v_company_id, v_client_id, v_product_id, v_prescription_qty, v_commission_rate;
        
        IF done THEN
            LEAVE read_loop;
        END IF;
        
        
        IF v_prescription_qty > 0 AND v_commission_rate > 0 THEN
            SET v_absorption_rate = (v_prescription_qty * v_commission_rate) / 100;
        ELSE
            SET v_absorption_rate = 0;
        END IF;
        
        
        UPDATE performance_records_absorption 
        SET 
            absorption_rate = v_absorption_rate,
            absorption_amount = v_absorption_rate * v_prescription_qty
        WHERE company_id = v_company_id 
        AND client_id = v_client_id 
        AND product_id = v_product_id
        AND settlement_month = p_settlement_month;
        
        SET updated_count = updated_count + 1;
        
    END LOOP;
    
    CLOSE absorption_cursor;
    
    RETURN CONCAT('Absorption rates calculated for settlement month: ', p_settlement_month, '. Updated ', updated_count, ' records.');
END ;;
DELIMITER ;
