CREATE DEFINER=`test`@`%` FUNCTION `check_performance_changes`(p_settlement_month VARCHAR(7)) RETURNS text CHARSET utf8mb4 COLLATE utf8mb4_uca1400_ai_ci
    READS SQL DATA
    DETERMINISTIC
BEGIN
    DECLARE v_added_count INT DEFAULT 0;
    DECLARE v_modified_count INT DEFAULT 0;
    DECLARE v_deleted_count INT DEFAULT 0;
    DECLARE result TEXT;
    
    
    SELECT COUNT(*) INTO v_added_count
    FROM performance_records_absorption
    WHERE settlement_month = p_settlement_month
    AND review_action = '추가';
    
    
    SELECT COUNT(*) INTO v_modified_count
    FROM performance_records_absorption
    WHERE settlement_month = p_settlement_month
    AND review_action = '수정';
    
    
    SELECT COUNT(*) INTO v_deleted_count
    FROM performance_records_absorption
    WHERE settlement_month = p_settlement_month
    AND review_action = '삭제';
    
    SET result = CONCAT(
        'Added: ', v_added_count, 
        ', Modified: ', v_modified_count, 
        ', Deleted: ', v_deleted_count
    );
    
    RETURN result;
END ;;
DELIMITER ;
