CREATE DEFINER=`test`@`%` FUNCTION `export_performance_records_to_csv`() RETURNS text CHARSET utf8mb4 COLLATE utf8mb4_uca1400_ai_ci
    READS SQL DATA
    DETERMINISTIC
BEGIN
    DECLARE csv_data TEXT DEFAULT '';
    
    
    SET csv_data = 'company_name,product_name,settlement_month,prescription_qty,commission_rate,created_at';
    
    
    SELECT 
        CONCAT(
            csv_data, '\n',
            GROUP_CONCAT(
                CONCAT(
                    COALESCE(c.company_name, ''), ',',
                    COALESCE(p.product_name, ''), ',',
                    COALESCE(pr.settlement_month, ''), ',',
                    COALESCE(pr.prescription_qty, 0), ',',
                    COALESCE(pr.commission_rate, 0), ',',
                    COALESCE(pr.created_at, '')
                )
                SEPARATOR '\n'
            )
        ) INTO csv_data
    FROM performance_records pr
    LEFT JOIN companies c ON pr.company_id = c.id
    LEFT JOIN products p ON pr.product_id = p.id
    LIMIT 100; 
    
    RETURN COALESCE(csv_data, 'No data available');
END ;;
DELIMITER ;
