CREATE DEFINER=`test`@`%` FUNCTION `get_settlement_summary_by_company`(p_settlement_month VARCHAR(7)) RETURNS text CHARSET utf8mb4 COLLATE utf8mb4_uca1400_ai_ci
    READS SQL DATA
    DETERMINISTIC
BEGIN
    DECLARE result TEXT DEFAULT '';
    
    
    SELECT 
        CONCAT(
            'Company: ', c.company_name, 
            ', Group: ', COALESCE(c.company_group, 'N/A'),
            ', Clients: ', COUNT(DISTINCT pr.client_id),
            ', Records: ', COUNT(pr.id),
            ', Total Amount: ', COALESCE(SUM(pr.prescription_qty * pr.commission_rate), 0)
        ) INTO result
    FROM companies c
    LEFT JOIN performance_records pr ON c.id = pr.company_id
    WHERE pr.settlement_month = p_settlement_month
    GROUP BY c.id, c.company_name, c.company_group
    LIMIT 1;
    
    RETURN COALESCE(result, 'No data found');
END ;;
DELIMITER ;
