CREATE DEFINER=`test`@`%` FUNCTION `update_company_approval_status`(p_company_id VARCHAR(36), p_new_status VARCHAR(20)) RETURNS text CHARSET utf8mb4 COLLATE utf8mb4_uca1400_ai_ci
    MODIFIES SQL DATA
    DETERMINISTIC
BEGIN
    DECLARE affected_rows INT DEFAULT 0;
    
    
    UPDATE companies 
    SET 
        approval_status = p_new_status,
        updated_at = NOW(),
        approved_at = CASE 
            WHEN p_new_status = 'approved' THEN NOW()
            ELSE approved_at
        END
    WHERE id = p_company_id;
    
    SET affected_rows = ROW_COUNT();
    
    IF affected_rows > 0 THEN
        RETURN CONCAT('Company approval status updated to: ', p_new_status);
    ELSE
        RETURN 'Company not found or no changes made';
    END IF;
END ;;
DELIMITER ;
