CREATE DEFINER=`test`@`%` PROCEDURE `calculate_absorption_rates_set_based`(IN p_settlement_month VARCHAR(7))
BEGIN
    
    UPDATE performance_records_absorption
    SET wholesale_revenue = 0,
        direct_revenue = 0,
        total_revenue = 0
    WHERE settlement_month = p_settlement_month;

    
    UPDATE performance_records_absorption aar
    INNER JOIN (
        SELECT
            ws.pharmacies_id AS match_client_id,
            ws.product_id    AS match_product_id,
            DATE_FORMAT(ws.sales_date, '%Y-%m') AS match_month,
            SUM(COALESCE(ws.sales_amount, 0)) AS wholesale_revenue
        FROM wholesale_sales ws
        WHERE DATE_FORMAT(ws.sales_date, '%Y-%m') = p_settlement_month
        GROUP BY ws.pharmacies_id, ws.product_id
    ) agg
    ON agg.match_client_id = aar.client_id
    AND agg.match_product_id = aar.product_id
    AND agg.match_month = p_settlement_month
    SET aar.wholesale_revenue = COALESCE(agg.wholesale_revenue, 0)
    WHERE aar.settlement_month = p_settlement_month;

    
    UPDATE performance_records_absorption aar
    INNER JOIN (
        SELECT
            ds.pharmacies_id AS match_client_id,
            ds.product_id    AS match_product_id,
            DATE_FORMAT(ds.sales_date, '%Y-%m') AS match_month,
            SUM(COALESCE(ds.sales_amount, 0)) AS direct_revenue
        FROM direct_sales ds
        WHERE DATE_FORMAT(ds.sales_date, '%Y-%m') = p_settlement_month
        GROUP BY ds.pharmacies_id, ds.product_id
    ) agg
    ON agg.match_client_id = aar.client_id
    AND agg.match_product_id = aar.product_id
    AND agg.match_month = p_settlement_month
    SET aar.direct_revenue = COALESCE(agg.direct_revenue, 0)
    WHERE aar.settlement_month = p_settlement_month;

    
    UPDATE performance_records_absorption
    SET total_revenue = COALESCE(wholesale_revenue, 0) + COALESCE(direct_revenue, 0)
    WHERE settlement_month = p_settlement_month;
END ;;
